List<GraphTreeSection> _sections() => [
      for (final m in jsonDecode(_fixture) as List)
        GraphTreeSection.fromMap((m as Map).cast<String, dynamic>()),
    ];

Widget _host({String? imageUrl, List<GraphTreeSection>? sections}) =>
    MaterialApp(
      theme: AymaTheme.light,
      home: Scaffold(
        body: SingleChildScrollView(
          child: FaceReportView(sections: sections ?? _sections(), imageUrl: imageUrl),
        ),
      ),
    );

bool _rich(Widget w, String text) =>
    w is RichText && w.text.toPlainText() == text;

void main() {
  testWidgets('the score renders as text with its band, no bar', (tester) async {
    await tester.pumpWidget(_host());
    await tester.pumpAndSettle();
    expect(find.text('FACIAL BEAUTY REPORT'), findsOneWidget);
    expect(find.byWidgetPredicate((w) => _rich(w, 'Face 6.9/10  Above average')),
        findsOneWidget);
    expect(find.byType(ScoreBar), findsNothing);
  });

  testWidgets('every element renders with its label', (tester) async {
    await tester.pumpWidget(_host());
    await tester.pumpAndSettle();
    for (final line in const [
      'Summary: Strong eyes, let down by skin texture',
      'Strength: Expressive, well-proportioned eyes',
      'Weakness: Even out skin texture',
      'Face shape: oval',
      'Best feature: eyes',
    ]) {
      expect(find.byWidgetPredicate((w) => _rich(w, line)), findsOneWidget,
          reason: line);
    }
    // the per-feature breakdown is text scores too — no bars
    expect(find.byWidgetPredicate((w) => _rich(w, 'Symmetry 7/10  Minor jaw asymmetry.')),
        findsOneWidget);
    // "what to do next" comes last
    expect(find.text('What to do next'), findsOneWidget);
    expect(find.text('Nightly retinoid for texture'), findsOneWidget);
    expect(
      tester.getTopLeft(find.text('Nightly retinoid for texture')).dy,
      greaterThan(tester.getTopLeft(find.text('What to do next')).dy),
    );
  });

  testWidgets('renders the analysed photo when an imageUrl is given',
      (tester) async {
    await tester.pumpWidget(_host(imageUrl: 'https://example.com/photo.jpg'));
    await tester.pump(); // don't settle — a real Image.network never resolves
    expect(find.byType(Image), findsOneWidget);
  });

  testWidgets('no photo, no crash', (tester) async {
    await tester.pumpWidget(_host());
    await tester.pumpAndSettle();
    expect(find.byType(Image), findsNothing);
    expect(tester.takeException(), isNull);
  });

  testWidgets('AddToStoryButton touch target is at least 48pt high',
      (tester) async {
    await tester.pumpWidget(_host());
    await tester.pumpAndSettle();
    final btn = find.byType(AddToStoryButton);
    expect(btn, findsOneWidget);
    expect(tester.getSize(btn).height, greaterThanOrEqualTo(48.0));
  });
}
